    public boolean isDamageTypeApplicable(String type, DamageSource source, float damage) {
        if(type.equals("cactus") || type.equals("inWall"))
            return false;
        if(source.isFireDamage()) {
            this.fireDamageAbsorbed += damage;
            return false;
        }
        if(type.equals("lightningBolt") && !this.isTamed()) {
        	this.transform(EntityZephyr.class, null, false);
        	return false;
		}
        return super.isDamageTypeApplicable(type, source, damage);
    }

    public void onLivingUpdate() {
        super.onLivingUpdate();

		if(!this.getEntityWorld().isRemote) {

			// Environmental Transformation:
			if(!this.isTamed()) {
				if (this.fireDamageAbsorbed >= 10) {
					this.transform(EntityZephyr.class, null, false);
				}
			}
		}
        
        // Particles:
        //if(this.getEntityWorld().isRemote)
            //this.getEntityWorld().spawnParticle(EnumParticleTypes.SNOWBALL, this.posX + (this.rand.nextDouble() - 0.5D) * (double)this.width, this.posY + this.rand.nextDouble() * (double)this.height, this.posZ + (this.rand.nextDouble() - 0.5D) * (double)this.width, 0.0D, 0.0D, 0.0D);
    }

public boolean attackEntityFrom(DamageSource damageSrc, float damage) {
	if(this.getEntityWorld().isRemote)
		return false;
    if(this.isEntityInvulnerable(damageSrc))
    	return false;
    if(!this.isDamageTypeApplicable(damageSrc.getDamageType(), damageSrc, damage))
    	return false;
    if(!this.isDamageEntityApplicable(damageSrc.getTrueSource()))
    	return false;
    damage *= this.getDamageModifier(damageSrc);
    damage = this.getDamageAfterDefense(damage);
    if(this.isBoss() || this.isRareSubspecies()) {
        if (!(damageSrc.getTrueSource() instanceof EntityPlayer))
            damage *= 0.25F;
    }
    
    if(super.attackEntityFrom(damageSrc, damage)) {
    	this.onDamage(damageSrc, damage);
        Entity entity = damageSrc.getImmediateSource();
        if(entity instanceof EntityThrowable)
        	entity = ((EntityThrowable)entity).getThrower();
        
        if(entity instanceof EntityLivingBase && this.getRider() != entity && this.getRidingEntity() != entity) {
            if(entity != this)
                this.setRevengeTarget((EntityLivingBase)entity);
            return true;
        }
        else
            return true;
    }
    return false;
}

    public boolean isEntityInvulnerable(DamageSource source) {
    	// Damage Limit:
    	if(this.damageLimit > 0) {
			if (this.damageTakenThisSec >= this.damageLimit)
				return true;
		}
        return super.isEntityInvulnerable(source);
    }

    public boolean isDamageTypeApplicable(String type, DamageSource source, float damage) {
        if(("inWall".equals(type) || "cactus".equals(type)) && (this.isRareSubspecies() || this.isBoss()))
            return false;
		if("inWall".equals(type))
			return !CreatureManager.getInstance().config.suffocationImmunity;
		if("drown".equals(type))
			return !CreatureManager.getInstance().config.drownImmunity;
        return true;
    }

	public EntityLivingBase transform(Class transformClass, Entity partner, boolean destroyPartner) {
		EntityLivingBase transformedEntity = null;
		try {
			transformedEntity = (EntityLivingBase)transformClass.getConstructor(new Class[]{World.class}).newInstance(this.getEntityWorld());
		}
		catch (Exception e) {
			e.printStackTrace();
		}
		if(transformedEntity == null) {
			return null;
		}

		// Creature Base:
		if(transformedEntity instanceof EntityCreatureBase) {
			EntityCreatureBase transformedCreature = (EntityCreatureBase) transformedEntity;
			transformedCreature.firstSpawn = false;

			// Temporary:
			if (this.isTemporary) {
				transformedCreature.setTemporary(this.temporaryDuration);
			}

			// Minion:
			if(this.isMinion()) {
				transformedCreature.setMinion(true);
			}

			// Master Target:
			if (this.hasMaster()) {
				transformedCreature.setMasterTarget(this.getMasterTarget());
			}

			// With Partner:
			if (partner != null && partner instanceof EntityCreatureBase) {
				EntityCreatureBase partnerCreature = (EntityCreatureBase) partner;
				Subspecies fusionSubspecies = transformedCreature.creatureInfo.getChildSubspecies(this, this.getSubspeciesIndex(), partnerCreature.getSubspecies());
				transformedCreature.applySubspecies(fusionSubspecies != null ? fusionSubspecies.index : 0, true);
				transformedCreature.setSizeScale(this.sizeScale + partnerCreature.sizeScale);

				// Level:
				int transformedLevel = this.getLevel();
				if("lowest".equalsIgnoreCase(CreatureManager.getInstance().config.elementalFusionLevelMix)) {
					if(transformedLevel > partnerCreature.getLevel()) {
						transformedLevel = partnerCreature.getLevel();
					}
				}
				else if("highest".equalsIgnoreCase(CreatureManager.getInstance().config.elementalFusionLevelMix)) {
					if(transformedLevel < partnerCreature.getLevel()) {
						transformedLevel = partnerCreature.getLevel();
					}
				}
				else {
					transformedLevel += partnerCreature.getLevel();
				}
				transformedCreature.applyLevel(Math.round(transformedLevel * (float)CreatureManager.getInstance().config.elementalFusionLevelMultiplier));

				// Tamed:
				if (transformedCreature instanceof EntityCreatureTameable) {
					EntityCreatureTameable fusionTameable = (EntityCreatureTameable) transformedCreature;
					Entity owner = null;
					if(this instanceof EntityCreatureTameable) {
						owner = ((EntityCreatureTameable)this).getPlayerOwner();
					}
					if (owner != null) {
						transformedCreature.applyLevel(transformedLevel);
						fusionTameable.setPlayerOwner((EntityPlayer)owner);
					}

					// Tamed Partner:
					else {
						Entity partnerOwner = null;
						if (partnerCreature instanceof EntityCreatureTameable) {
							partnerOwner = ((EntityCreatureTameable)partnerCreature).getPlayerOwner();
						}
						if (partnerOwner != null) {
							transformedCreature.applyLevel(transformedLevel);
							fusionTameable.setPlayerOwner((EntityPlayer) partnerOwner);

							// Temporary:
							if (partnerCreature.isTemporary) {
								transformedCreature.setTemporary(partnerCreature.temporaryDuration);
							}

							// Minion:
							transformedCreature.setMinion(partnerCreature.isMinion());

							// Master Target:
							if (partnerCreature.hasMaster()) {
								transformedCreature.setMasterTarget(partnerCreature.getMasterTarget());
							}
						}
					}
				}
			}

			// Without Partner:
			else {
				transformedCreature.applySubspecies(this.getSubspeciesIndex(), true);
				transformedCreature.setSizeScale(this.sizeScale);
				transformedCreature.applyLevel(this.getLevel());

				// Tamed:
				if (transformedCreature instanceof EntityCreatureTameable) {
					EntityCreatureTameable fusionTameable = (EntityCreatureTameable) transformedCreature;
					if (this.getOwner() != null && this.getOwner() instanceof EntityPlayer) {
						fusionTameable.setPlayerOwner((EntityPlayer) this.getOwner());
					}
				}
			}
		}

		// Transformed Entity:
		transformedEntity.setLocationAndAngles(this.posX, this.posY, this.posZ, this.rotationYaw, this.rotationPitch);
		this.getEntityWorld().spawnEntity(transformedEntity);

		// Remove Parts:
		this.setDead();
		if(partner != null && destroyPartner) {
			partner.setDead();
		}

		return transformedEntity;
	}

    public boolean attackEntityFrom(DamageSource damageSrc, float damage) {
        if (this.isEntityInvulnerable(damageSrc))
            return false;
        else {
            if(!this.isPassive())
            	this.setSitting(false);

            Entity entity = damageSrc.getImmediateSource();
            if(entity instanceof EntityThrowable)
            	entity = ((EntityThrowable)entity).getThrower();
            
            if(this.isTamed() && this.getOwner() == entity)
            	return false;

            return super.attackEntityFrom(damageSrc, damage);
        }
    }

public boolean isTamed() {
    try {
        return (this.getByteFromDataManager(TAMED) & TAMED_ID.IS_TAMED.id) != 0;
    }
    catch (Exception e) {
        return false;
    }
}

public EntityZephyr(World world) {
    super(world);
    
    // Setup:
    this.attribute = EnumCreatureAttribute.UNDEFINED;
    this.hasAttackSound = false;
    this.setupMob();
}

public boolean isDamageTypeApplicable(String type, DamageSource source, float damage) {
	if("lightningBolt".equalsIgnoreCase(type))
		return false;
	return super.isDamageTypeApplicable(type, source, damage);
}

	public void register() {
		if(this.dummy)
			return;

		// ID and Enabled Check:
		if(!this.enabled) {
			LycanitesMobs.printDebug("Creature", "Creature Disabled: " + this.getName() + " - " + this.entityClass + " (" + group.name + ")");
		}

		// Mapping and Registration:
		if(!ObjectManager.entityLists.containsKey(this.group.filename)) {
			ObjectManager.entityLists.put(this.group.filename, new EntityListCustom());
		}
		ObjectManager.entityLists.get(this.group.filename).addMapping(this.entityClass, this.getResourceLocation(), this.eggBackColor, this.eggForeColor);
		EntityRegistry.registerModEntity(this.getResourceLocation(), this.entityClass, this.getName(), this.group.getNextMobID(), this.group.mod, 128, 3, true);

		// Add Stats:
		ItemStack achievementStack = new ItemStack(ObjectManager.getItem("mobtoken"));
		achievementStack.setTagInfo("Mob", new NBTTagString(this.getName()));
		ObjectManager.addStat(this.getName() + ".kill", new StatBase(this.getName() + ".kill", new TextComponentString(this.getName() + ".kill")));
		ObjectManager.addStat(this.getName() + ".learn", new StatBase(this.getName() + ".learn", new TextComponentString(this.getName() + ".learn")));
		if(this.isSummonable()) {
			ObjectManager.addStat(this.getName() + ".summon", new StatBase(this.getName() + ".summon", new TextComponentString(this.getName() + ".summon")));
		}
		if(this.isTameable()) {
			ObjectManager.addStat(this.getName() + ".tame", new StatBase(this.getName() + ".tame", new TextComponentString(this.getName() + ".tame")));
		}

		// Add Sounds:
		AssetManager.addSound(name + "_say", group, "entity." + name + ".say");
		AssetManager.addSound(name + "_hurt", group, "entity." + name + ".hurt");
		AssetManager.addSound(name + "_death", group, "entity." + name + ".death");
		AssetManager.addSound(name + "_step", group, "entity." + name + ".step");
		AssetManager.addSound(name + "_attack", group, "entity." + name + ".attack");
		AssetManager.addSound(name + "_jump", group, "entity." + name + ".jump");
		AssetManager.addSound(name + "_fly", group, "entity." + name + ".fly");
		if(this.isSummonable() || this.isTameable() || EntityCreatureTameable.class.isAssignableFrom(this.entityClass)) {
			AssetManager.addSound(name + "_tame", group, "entity." + name + ".tame");
			AssetManager.addSound(name + "_beg", group, "entity." + name + ".beg");
		}
		if(this.isTameable())
			AssetManager.addSound(name + "_eat", group, "entity." + name + ".eat");
		if(this.isMountable())
			AssetManager.addSound(name + "_mount", group, "entity." + name + ".mount");
		if(this.isBoss())
			AssetManager.addSound(name + "_phase", group, "entity." + name + ".phase");

		// Register Spawning:
		this.creatureSpawn.register(this);

		// Debug Message - Added:
		LycanitesMobs.printDebug("Creature", "Creature Added: " + this.getName() + " - " + this.entityClass + " (" + this.group.name + ")");
	}
